targets = subprocess.run(['bash','-c','ls client/src/pages/landing-phone/*.ts client/src/pages/landing-phone/*.tsx client/src/pages/landing-phone/scenes/*.tsx client/src/pages/landingRuntime.ts'],cwd='/home/runner/workspace',capture_output=True,text=True).stdout.split()
cur={}
for t in targets:
    p='/home/runner/workspace/'+t
    cur[hashlib.sha1(open(p,'rb').read()).hexdigest()]=t
print('current files:',len(cur))
matches={}
for snap in glob.glob('*/*@v*'):
    try: h=hashlib.sha1(open(snap,'rb').read()).hexdigest()
    except: continue
    if h in cur:
        matches.setdefault(cur[h],[]).append(snap)
for k,v in sorted(matches.items()):
    print('IDENTICAL-TO-SNAPSHOT:',k,'->',v[:3])
print('---')
print('no snapshot match for:', sorted(set(cur.values())-set(matches)))
EOF

